S_ANY = "?"
S_LAZY = "*"
S_GREEDY = "#"
S_FLAG = "~"
S_NEG = "!"
S_OPEN = "<"
S_CLOSE = ">"
S_ALT = ","
S_REF = "$"
HAS_CLASS = True
HAS_FLAG = True
HAS_CAPS = False
HAS_GROUPS = False
HAS_REF = False


class Err(Exception):
    pass


def lower(c):
    return chr(ord(c) + 32) if "A" <= c <= "Z" else c


def swap(c):
    if "a" <= c <= "z":
        return chr(ord(c) - 32)
    if "A" <= c <= "Z":
        return chr(ord(c) + 32)
    return c


class Parser:
    def __init__(self, pat):
        self.pat = pat
        self.n = len(pat)
        self.count = 0
        self.closed = set()

    def newcap(self):
        if not HAS_CAPS:
            return 0
        self.count += 1
        return self.count

    def alts(self, i, depth):
        """parse alternatives up to a close char (depth > 0) or the end; returns (alts, i)"""
        out = []
        while True:
            seq, i = self.seq(i, depth)
            out.append(seq)
            if depth > 0 and i < self.n and self.pat[i] == S_ALT:
                i += 1
                continue
            return out, i

    def seq(self, i, depth):
        pat, n = self.pat, self.n
        items = []
        while i < n:
            c = pat[i]
            if depth > 0 and c == S_ALT and HAS_GROUPS:
                break
            if HAS_GROUPS and c == S_CLOSE:
                if depth == 0:
                    raise Err("error: pattern at %d: group" % (i + 1))
                break
            if c == "\\":
                if i + 1 >= n:
                    raise Err("error: pattern at %d: escape" % (i + 1))
                items.append(("lit", pat[i + 1]))
                i += 2
            elif c == S_ANY:
                num = self.newcap()
                items.append(("any", num))
                if num:
                    self.closed.add(num)
                i += 1
            elif c == S_LAZY:
                num = self.newcap()
                items.append(("lazy", num))
                if num:
                    self.closed.add(num)
                i += 1
            elif HAS_REF and c == S_GREEDY:
                num = self.newcap()
                items.append(("greedy", num))
                if num:
                    self.closed.add(num)
                i += 1
            elif HAS_CLASS and c == "[":
                it, i = self.cls(i)
                items.append(it)
            elif HAS_GROUPS and c == S_OPEN:
                num = self.newcap()
                alts, j = self.alts(i + 1, depth + 1)
                if j >= n:
                    raise Err("error: pattern at %d: group" % (i + 1))
                if num:
                    self.closed.add(num)
                items.append(("grp", num, alts))
                i = j + 1
            elif HAS_REF and c == S_REF:
                if i + 1 >= n or not ("1" <= pat[i + 1] <= "9") or int(pat[i + 1]) not in self.closed:
                    raise Err("error: pattern at %d: reference" % (i + 1))
                items.append(("ref", int(pat[i + 1])))
                i += 2
            else:
                items.append(("lit", c))
                i += 1
        return items, i

    def cls(self, start):
        pat, n = self.pat, self.n
        j = start + 1
        neg = False
        if j < n and pat[j] == S_NEG:
            neg = True
            j += 1
        ranges = []
        first = True
        while True:
            if j >= n:
                raise Err("error: pattern at %d: class" % (start + 1))
            c = pat[j]
            if c == "]" and not first:
                j += 1
                break
            first = False
            lo_at = j
            if c == "\\":
                if j + 1 >= n:
                    raise Err("error: pattern at %d: class" % (start + 1))
                lo = pat[j + 1]
                j += 2
            else:
                lo = c
                j += 1
            if j + 1 < n and pat[j] == "-" and pat[j + 1] != "]":
                if pat[j + 1] == "\\":
                    if j + 2 >= n:
                        raise Err("error: pattern at %d: class" % (start + 1))
                    hi = pat[j + 2]
                    j += 3
                else:
                    hi = pat[j + 1]
                    j += 2
                if hi < lo:
                    raise Err("error: pattern at %d: range" % (lo_at + 1))
                ranges.append((lo, hi))
            else:
                ranges.append((lo, lo))
        num = self.newcap()
        if num:
            self.closed.add(num)
        return ("cls", ranges, neg, num), j


def stencil(pattern, text):
    try:
        return do_match(pattern, text)
    except Err as e:
        return str(e)


def do_match(pattern, text):
    fold = False
    body = pattern
    off = 0
    if HAS_FLAG and pattern[:1] == S_FLAG:
        fold = True
        off = 1
    p = Parser(pattern)
    p.pat = pattern
    items, i = p.alts(off, 0)
    root = items[0]
    T = text
    caps = [None] * (p.count + 1)

    def eq(a, b):
        return lower(a) == lower(b) if fold else a == b

    def inclass(ch, ranges, neg):
        hit = False
        for lo, hi in ranges:
            if lo <= ch <= hi or (fold and lo <= swap(ch) <= hi):
                hit = True
        return hit != neg

    def setcap(num, s, e):
        old = caps[num] if num else None
        if num:
            caps[num] = (s, e)
        return old

    def resume(cont, pos):
        if cont is None:
            return pos == len(T)
        if cont[0] == "seq":
            return run(cont[1], cont[2], pos, cont[3])
        g, start, nxt = cont[1], cont[2], cont[3]
        old = caps[g]
        caps[g] = (start, pos)
        if resume(nxt, pos):
            return True
        caps[g] = old
        return False

    def run(seq, idx, pos, cont):
        if idx == len(seq):
            return resume(cont, pos)
        it = seq[idx]
        k = it[0]
        if k == "lit":
            return pos < len(T) and eq(T[pos], it[1]) and run(seq, idx + 1, pos + 1, cont)
        if k == "any":
            if pos >= len(T):
                return False
            old = setcap(it[1], pos, pos + 1)
            if run(seq, idx + 1, pos + 1, cont):
                return True
            if it[1]:
                caps[it[1]] = old
            return False
        if k == "cls":
            if pos >= len(T) or not inclass(T[pos], it[1], it[2]):
                return False
            old = setcap(it[3], pos, pos + 1)
            if run(seq, idx + 1, pos + 1, cont):
                return True
            if it[3]:
                caps[it[3]] = old
            return False
        if k in ("lazy", "greedy"):
            span = range(0, len(T) - pos + 1) if k == "lazy" else range(len(T) - pos, -1, -1)
            for w in span:
                old = setcap(it[1], pos, pos + w)
                if run(seq, idx + 1, pos + w, cont):
                    return True
                if it[1]:
                    caps[it[1]] = old
            return False
        if k == "grp":
            for alt in it[2]:
                frame = ("end", it[1], pos, ("seq", seq, idx + 1, cont))
                if run(alt, 0, pos, frame):
                    return True
            return False
        if k == "ref":
            c = caps[it[1]]
            if c is None:
                return False
            s = T[c[0]:c[1]]
            w = len(s)
            if pos + w > len(T):
                return False
            for a, b in zip(s, T[pos:pos + w]):
                if not eq(a, b):
                    return False
            return run(seq, idx + 1, pos + w, cont)
        raise AssertionError(k)

    if not run(root, 0, 0, None):
        return "no"
    if not HAS_CAPS:
        return "yes"
    out = "yes"
    for c in caps[1:]:
        out += " [%s]" % ("" if c is None else T[c[0]:c[1]])
    return out

