use stencil::stencil;

#[test]
fn cases() {
    let cases: Vec<(Vec<&str>, &str)> = vec![
        (vec!["ab*ef", "abcdef"], "yes [cd]"),
        (vec!["_at*", "cattle"], "yes [c] [tle]"),
        (vec!["a_c", "ac"], "no"),
        (vec!["~stop*", "STOPPING"], "yes [PING]"),
        (vec!["[a-c]_[!0-9]", "b2x"], "yes [b] [2] [x]"),
        (vec!["<cat,dog>*", "dogs"], "yes [dog] [s]"),
        (vec!["<*>&1", "abab"], "yes [ab] [ab]"),
    ];
    for (i, (a, want)) in cases.iter().enumerate() {
        let got = stencil(a[0], a[1]);
        assert_eq!(got, *want, "case {} {:?}", i, a);
    }
}
